input.command:
cat provider.tf; cat > main.tf <<'EOF'
resource "aws_sqs_queue" "jobs" {
  name_prefix                = "jobs-"
  visibility_timeout_seconds = 300
  message_retention_seconds  = 345600
  tags = {
    team   = "billing"
    oncall = "INC-2291"
  }
}

output "jobs_queue_url" {
  value = aws_sqs_queue.jobs.url
}
EOF
terraform plan -detailed-exitcode -no-color 2>&1 | tail -8; echo exit=$?

